  1→//! Non-interactive UI for CI/headless environments.
  2→
  3→use std::collections::HashMap;
  4→use std::time::Duration;
  5→
  6→use crate::error::{BivvyError, Result};
  7→
  8→use super::progress::format_duration;
  9→use super::theme::BivvyTheme;
 10→use super::{
 11→    OutputMode, Prompt, PromptResult, PromptType, RunSummary, SpinnerHandle, StatusKind,
 12→    UserInterface,
 13→};
 14→
 15→/// UI implementation for non-interactive mode.
 16→///
 17→/// When running in CI (detected via `is_ci()`), the progress bar is
 18→/// suppressed since it produces noisy output in log-based environments.
 19→/// All other output (headers, summaries, errors) is preserved.
 20→pub struct NonInteractiveUI {
 21→    mode: OutputMode,
 22→    env_overrides: HashMap<String, String>,
 23→    is_ci: bool,
 24→}
 25→
 26→impl NonInteractiveUI {
 27→    /// Create a new non-interactive UI.
 28→    pub fn new(mode: OutputMode) -> Self {
 29→        // Collect BIVVY_PROMPT_* env vars
 30→        let env_overrides: HashMap<String, String> = std::env::vars()
 31→            .filter(|(k, _)| k.starts_with("BIVVY_PROMPT_"))
 32→            .collect();
 33→
 34→        Self {
 35→            mode,
 36→            env_overrides,
 37→            is_ci: crate::shell::is_ci(),
 38→        }
 39→    }
 40→
 41→    /// Create with explicit overrides (for testing).
 42→    pub fn with_overrides(mode: OutputMode, overrides: HashMap<String, String>) -> Self {
 43→        Self {
 44→            mode,
 45→            env_overrides: overrides,
 46→            is_ci: false,
 47→        }
 48→    }
 49→
 50→    /// Create with explicit CI flag (for testing).
 51→    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
 52→        let env_overrides: HashMap<String, String> = std::env::vars()
 53→            .filter(|(k, _)| k.starts_with("BIVVY_PROMPT_"))
 54→            .collect();
 55→
 56→        Self {
 57→            mode,
 58→            env_overrides,
 59→            is_ci,
 60→        }
 61→    }
 62→}
 63→
 64→impl UserInterface for NonInteractiveUI {
 65→    fn output_mode(&self) -> OutputMode {
 66→        self.mode
 67→    }
 68→
 69→    fn message(&mut self, msg: &str) {
 70→        if self.mode.shows_status() {
 71→            println!("{}", msg);
 72→        }
 73→    }
 74→
 75→    fn success(&mut self, msg: &str) {
 76→        if self.mode.shows_status() {
 77→            println!("✓ {}", msg);
 78→        }
 79→    }
 80→
 81→    fn warning(&mut self, msg: &str) {
 82→        if self.mode.shows_status() {
 83→            eprintln!("⚠ {}", msg);
 84→        }
 85→    }
 86→
 87→    fn error(&mut self, msg: &str) {
 88→        eprintln!("✗ {}", msg);
 89→    }
 90→
 91→    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
 92→        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
 93→
 94→        // Check environment override
 95→        let env_key = format!("BIVVY_PROMPT_{}", prompt.key.to_uppercase());
 96→        if let Some(value) = self.env_overrides.get(&env_key) {
 97→            if is_multiselect {
 98→                let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
 99→                return Ok(PromptResult::Strings(values));
100→            }
101→            return Ok(PromptResult::String(value.clone()));
102→        }
103→
104→        // Use default
105→        if let Some(default) = &prompt.default {
106→            if is_multiselect {
107→                let values: Vec<String> =
108→                    default.split(',').map(|s| s.trim().to_string()).collect();
109→                return Ok(PromptResult::Strings(values));
110→            }
111→            return Ok(PromptResult::String(default.clone()));
112→        }
113→
114→        Err(BivvyError::ConfigValidationError {
115→            message: format!(
116→                "Cannot prompt for '{}' in non-interactive mode (no default value)",
117→                prompt.key
118→            ),
119→        })
120→    }
121→
122→    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
123→        if self.mode.shows_spinners() {
124→            println!("  {}", message);
125→        }
126→        Box::new(NoopSpinner { indent: 0 })
127→    }
128→
129→    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
130→        if self.mode.shows_spinners() {
131→            let prefix = " ".repeat(indent);
132→            println!("{}{}", prefix, message);
133→        }
134→        Box::new(NoopSpinner { indent })
135→    }
136→
137→    fn show_header(&mut self, title: &str) {
138→        if self.mode.shows_status() {
139→            println!("\n{}\n", title);
140→        }
141→    }
142→
143→    fn show_progress(&mut self, current: usize, total: usize) {
144→        if self.mode.shows_status() {
145→            println!("[{}/{}]", current, total);
146→        }
147→    }
148→
149→    fn show_run_header(
150→        &mut self,
151→        app_name: &str,
152→        workflow: &str,
153→        step_count: usize,
154→        version: &str,
155→    ) {
156→        if self.mode.shows_status() {
157→            let step_label = if step_count == 1 { "step" } else { "steps" };
158→            println!(
159→                "\n⛺ {} v{} · {} workflow · {} {}\n",
160→                app_name, version, workflow, step_count, step_label
161→            );
162→        }
163→    }
164→
165→    fn show_workflow_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
166→        if self.is_ci {
167→            return;
168→        }
169→        if self.mode.shows_status() {
170→            let filled = if total > 0 { (current * 16) / total } else { 0 };
171→            let empty = 16 - filled;
172→            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
173→            println!(
174→                "  [{}] {}/{} steps · {} elapsed",
175→                bar,
176→                current,
177→                total,
178→                format_duration(elapsed),
179→            );
180→        }
181→    }
182→
183→    fn show_hint(&mut self, hint: &str) {
184→        if self.mode.shows_status() {
185→            println!("  💡 {}", hint);
186→        }
187→    }
188→
189→    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
190→        eprintln!();
191→        eprintln!("    ┌─ Command ──────────────────────────");
192→        eprintln!("    │ {}", command);
193→        if !output.is_empty() {
194→            eprintln!("    ├─ Output ───────────────────────────");
195→            for line in output.lines() {
196→                eprintln!("    │ {}", line);
197→            }
198→        }
199→        eprintln!("    └────────────────────────────────────");
200→        if let Some(h) = hint {
201→            eprintln!();
202→            eprintln!("    Hint: {}", h);
203→        }
204→    }
205→
206→    fn show_run_summary(&mut self, summary: &RunSummary) {
207→        if !self.mode.shows_status() {
208→            return;
209→        }
210→
211→        println!();
212→        println!("  ┌─ Summary ──────────────────────────");
213→
214→        for step in &summary.step_results {
215→            let icon = step.status.icon();
216→            let duration_str = step.duration.map(format_duration).unwrap_or_default();
217→            let detail_str = step.detail.as_deref().unwrap_or("");
218→
219→            let right_side = if !duration_str.is_empty() {
220→                duration_str
221→            } else if !detail_str.is_empty() {
222→                detail_str.to_string()
223→            } else {
224→                String::new()
225→            };
226→
227→            println!("  │ {} {:<20} {}", icon, step.name, right_side);
228→        }
229→
230→        println!("  ├────────────────────────────────────");
231→        println!(
232→            "  │ Total: {} · {} run · {} skipped",
233→            format_duration(summary.total_duration),
234→            summary.steps_run,
235→            summary.steps_skipped,
236→        );
237→        println!("  └────────────────────────────────────");
238→
239→        if summary.success {
240→            println!("  ✓ Setup complete!");
241→        } else {
242→            let status = StatusKind::Failed;
243→            eprintln!(
244→                "  {} Setup failed: {}",
245→                status.icon(),
246→                summary.failed_steps.join(", ")
247→            );
248→        }
249→    }
