 22→
 23→/// The run command implementation.
 24→pub struct RunCommand {
 25→    project_root: PathBuf,
 26→    args: RunArgs,
 27→}
 28→
 29→impl RunCommand {
 30→    /// Create a new run command.
 31→    pub fn new(project_root: &Path, args: RunArgs) -> Self {
 32→        Self {
 33→            project_root: project_root.to_path_buf(),
 34→            args,
 35→        }
 36→    }
 37→
 38→    /// Get the project root path.
 39→    pub fn project_root(&self) -> &Path {
 40→        &self.project_root
 41→    }
 42→
 43→    /// Get the command arguments.
 44→    pub fn args(&self) -> &RunArgs {
 45→        &self.args
 46→    }
 47→
 48→    /// Build run options from args.
 49→    fn build_options(&self) -> RunOptions {
 50→        let skip_behavior = match self.args.skip_behavior.as_str() {
 51→            "skip_only" => SkipBehavior::SkipOnly,
 52→            "run_anyway" => SkipBehavior::RunAnyway,
 53→            _ => SkipBehavior::SkipWithDependents,
 54→        };
 55→
 56→        RunOptions {
 57→            workflow: Some(self.args.workflow.clone()),
 58→            only: self.args.only.iter().cloned().collect(),
 59→            skip: self.args.skip.iter().cloned().collect(),
 60→            skip_behavior,
 61→            force: self.args.force.iter().cloned().collect(),
 62→            dry_run: self.args.dry_run,
 63→            provided_requirements: HashSet::new(),
 64→            active_environment: None,
 65→        }
 66→    }
 67→
 68→    /// Resolve the target environment using the priority chain.
 69→    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
 70→        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
 71→    }
 72→
 73→    /// Resolve steps from configuration.
 74→    ///
 75→    /// Steps with a `template` field are resolved through the Registry,
 76→    /// which merges template defaults with config overrides. Steps without
 77→    /// a template are treated as inline definitions.
 78→    fn resolve_steps(
 79→        &self,
 80→        config: &crate::config::BivvyConfig,
 81→        environment: Option<&str>,
 82→    ) -> Result<HashMap<String, ResolvedStep>> {
 83→        let registry = if config.template_sources.is_empty() {
 84→            Registry::new(Some(&self.project_root))?
 85→        } else {
 86→            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
 87→        };
 88→
 89→        let mut steps = HashMap::new();
 90→        for (name, step_config) in &config.steps {
 91→            let resolved = if let Some(template_name) = &step_config.template {
 92→                let (template, _source) = registry.resolve(template_name)?;
 93→                ResolvedStep::from_template(
 94→                    name,
 95→                    template,
 96→                    step_config,
 97→                    &step_config.inputs,
 98→                    environment,
 99→                )
100→            } else {
101→                ResolvedStep::from_config(name, step_config, environment)
102→            };
103→            steps.insert(name.clone(), resolved);
104→        }
105→        Ok(steps)
106→    }
107→}
108→
109→impl Command for RunCommand {
110→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
111→        // Load configuration
112→        let config = match load_merged_config(&self.project_root) {
113→            Ok(c) => c,
114→            Err(BivvyError::ConfigNotFound { .. }) => {
115→                ui.error("No configuration found. Run 'bivvy init' first.");
116→                return Ok(CommandResult::failure(2));
117→            }
118→            Err(e) => return Err(e),
119→        };
120→
121→        // Deprecation warning for --ci flag
122→        if self.args.ci {
123→            ui.warning(
124→                "--ci is deprecated and will be removed in 2.0. \
125→                 Use --non-interactive and --env ci instead.",
126→            );
127→        }
128→
129→        // Apply config default_output when no CLI flag was explicitly set.
130→        // OutputMode::Normal means the user didn't pass --verbose or --quiet.
131→        if ui.output_mode() == OutputMode::Normal {
132→            ui.set_output_mode(config.settings.default_output.into());
133→        }
134→
135→        // Resolve environment (before header so we can use resolved workflow)
136→        let resolved_env = self.resolve_environment(&config);
137→        let env_name = resolved_env.name.clone();
138→
139→        // Warn if the environment is not known
140→        if !resolved_env.is_known(&config) {
141→            ui.warning(&format!(
142→                "Unknown environment '{}'. It is not defined in settings.environments                  or a built-in. Step overrides for this environment will have no effect.",
143→                env_name
144→            ));
145→        }
146→
147→        // Get provided_requirements from environment config
148→        let provided_requirements: HashSet<String> = config
149→            .settings
150→            .environments
151→            .get(&env_name)
152→            .map(|env_config| env_config.provided_requirements.iter().cloned().collect())
153→            .unwrap_or_default();
154→
155→        // Use environment's default_workflow if no explicit --workflow and config has one
156→        let workflow_name = if self.args.workflow == "default" {
157→            config
158→                .settings
159→                .environments
160→                .get(&env_name)
161→                .and_then(|env_config| env_config.default_workflow.clone())
162→                .unwrap_or_else(|| self.args.workflow.clone())
163→        } else {
164→            self.args.workflow.clone()
165→        };
166→
167→        // Show header
168→        let app_name = config.app_name.as_deref().unwrap_or("project");
169→        let step_count = config
170→            .workflows
171→            .get(workflow_name.as_str())
172→            .map(|w| w.steps.len())
173→            .unwrap_or(0);
174→        ui.show_run_header(
175→            app_name,
176→            &workflow_name,
177→            step_count,
178→            crate::updates::version::VERSION,
179→        );
180→
181→        // Show environment and config info
182→        ui.message(&format!(
183→            "  Environment: {} ({})",
184→            env_name, resolved_env.source
185→        ));
186→
187→        if self.args.dry_run {
188→            let paths = ConfigPaths::discover(&self.project_root);
189→            if let Some(project_path) = &paths.project {
190→                ui.message(&format!("Config: {}", project_path.display()));
191→            }
192→        }
193→
194→        // Check for dry-run mode
195→        if self.args.dry_run {
196→            ui.message("Running in dry-run mode - no commands will be executed");
197→        }
198→
199→        // Get project identity
200→        let project_id = ProjectId::from_path(&self.project_root)?;

