//! Non-interactive UI for CI/headless environments.

use std::collections::HashMap;
use std::time::Duration;

use crate::error::{BivvyError, Result};

use super::progress::format_duration;
use super::theme::BivvyTheme;
use super::{
    OutputMode, Prompt, PromptResult, PromptType, RunSummary, SpinnerHandle, StatusKind,
    UserInterface,
};

/// UI implementation for non-interactive mode.
///
/// When running in CI (detected via `is_ci()`), the progress bar is
/// suppressed since it produces noisy output in log-based environments.
/// All other output (headers, summaries, errors) is preserved.
pub struct NonInteractiveUI {
    mode: OutputMode,
    env_overrides: HashMap<String, String>,
    is_ci: bool,
}

impl NonInteractiveUI {
    /// Create a new non-interactive UI.
    pub fn new(mode: OutputMode) -> Self {
        // Collect BIVVY_PROMPT_* env vars
        let env_overrides: HashMap<String, String> = std::env::vars()
            .filter(|(k, _)| k.starts_with("BIVVY_PROMPT_"))
            .collect();

        Self {
            mode,
            env_overrides,
            is_ci: crate::shell::is_ci(),
        }
    }

    /// Create with explicit overrides (for testing).
    pub fn with_overrides(mode: OutputMode, overrides: HashMap<String, String>) -> Self {
        Self {
            mode,
            env_overrides: overrides,
            is_ci: false,
        }
    }

    /// Create with explicit CI flag (for testing).
    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
        let env_overrides: HashMap<String, String> = std::env::vars()
            .filter(|(k, _)| k.starts_with("BIVVY_PROMPT_"))
            .collect();

        Self {
            mode,
            env_overrides,
            is_ci,
        }
    }
}

impl UserInterface for NonInteractiveUI {
    fn output_mode(&self) -> OutputMode {
        self.mode
    }

    fn message(&mut self, msg: &str) {
        if self.mode.shows_status() {
            println!("{}", msg);
        }
    }

    fn success(&mut self, msg: &str) {
        if self.mode.shows_status() {
            println!("✓ {}", msg);
        }
    }

    fn warning(&mut self, msg: &str) {
        if self.mode.shows_status() {
            eprintln!("⚠ {}", msg);
        }
    }

    fn error(&mut self, msg: &str) {
        eprintln!("✗ {}", msg);
    }

    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });

        // Check environment override
        let env_key = format!("BIVVY_PROMPT_{}", prompt.key.to_uppercase());
        if let Some(value) = self.env_overrides.get(&env_key) {
            if is_multiselect {
                let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(PromptResult::Strings(values));
            }
            return Ok(PromptResult::String(value.clone()));
        }

        // Use default
        if let Some(default) = &prompt.default {
            if is_multiselect {
                let values: Vec<String> =
                    default.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(PromptResult::Strings(values));
            }
            return Ok(PromptResult::String(default.clone()));
        }

        Err(BivvyError::ConfigValidationError {
            message: format!(
                "Cannot prompt for '{}' in non-interactive mode (no default value)",
                prompt.key
            ),
        })
    }

    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
        if self.mode.shows_spinners() {
            println!("  {}", message);
        }
        Box::new(NoopSpinner { indent: 0 })
    }

    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
        if self.mode.shows_spinners() {
            let prefix = " ".repeat(indent);
            println!("{}{}", prefix, message);
        }
        Box::new(NoopSpinner { indent })
    }

    fn show_header(&mut self, title: &str) {
        if self.mode.shows_status() {
            println!("\n{}\n", title);
        }
    }

    fn show_progress(&mut self, current: usize, total: usize) {
        if self.mode.shows_status() {
            println!("[{}/{}]", current, total);
        }
    }

    fn show_run_header(
        &mut self,
        app_name: &str,
        workflow: &str,
        step_count: usize,
        version: &str,
    ) {
        if self.mode.shows_status() {
            let step_label = if step_count == 1 { "step" } else { "steps" };
            println!(
                "\n⛺ {} v{} · {} workflow · {} {}\n",
                app_name, version, workflow, step_count, step_label
            );
        }
    }

    fn show_workflow_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
        if self.is_ci {
            return;
        }
        if self.mode.shows_status() {
            let filled = if total > 0 { (current * 16) / total } else { 0 };
            let empty = 16 - filled;
            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
            println!(
                "  [{}] {}/{} steps · {} elapsed",
                bar,
                current,
                total,
                format_duration(elapsed),
            );
        }
    }

    fn show_hint(&mut self, hint: &str) {
        if self.mode.shows_status() {
            println!("  💡 {}", hint);
        }
    }

    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
        eprintln!();
        eprintln!("    ┌─ Command ──────────────────────────");
        eprintln!("    │ {}", command);
        if !output.is_empty() {
            eprintln!("    ├─ Output ───────────────────────────");
            for line in output.lines() {
                eprintln!("    │ {}", line);
            }
        }
        eprintln!("    └────────────────────────────────────");
        if let Some(h) = hint {
            eprintln!();
            eprintln!("    Hint: {}", h);
        }
    }

    fn show_run_summary(&mut self, summary: &RunSummary) {
        if !self.mode.shows_status() {
            return;
        }

        println!();
        println!("  ┌─ Summary ──────────────────────────");

        for step in &summary.step_results {
            let icon = step.status.icon();
            let duration_str = step.duration.map(format_duration).unwrap_or_default();
            let detail_str = step.detail.as_deref().unwrap_or("");

            let right_side = if !duration_str.is_empty() {
                duration_str
            } else if !detail_str.is_empty() {
                detail_str.to_string()
            } else {
                String::new()
            };

            println!("  │ {} {:<20} {}", icon, step.name, right_side);
        }

        println!("  ├────────────────────────────────────");
        println!(
            "  │ Total: {} · {} run · {} skipped",
            format_duration(summary.total_duration),
            summary.steps_run,
            summary.steps_skipped,
        );
        println!("  └────────────────────────────────────");

        if summary.success {
            println!("  ✓ Setup complete!");
        } else {
            let status = StatusKind::Failed;
            eprintln!(
                "  {} Setup failed: {}",
                status.icon(),
                summary.failed_steps.join(", ")
            );
        }
    }

    fn is_interactive(&self) -> bool {
        false
    }

    fn set_output_mode(&mut self, mode: OutputMode) {
        self.mode = mode;
    }
}

/// Spinner that does nothing (for non-interactive mode).
struct NoopSpinner {
    indent: usize,
}

impl SpinnerHandle for NoopSpinner {
    fn set_message(&mut self, _msg: &str) {}

    fn finish_success(&mut self, msg: &str) {
        let prefix = " ".repeat(self.indent);
        let theme = BivvyTheme::new();
        println!("{}{}", prefix, theme.format_success(msg));
    }

    fn finish_error(&mut self, msg: &str) {
        let prefix = " ".repeat(self.indent);
        let theme = BivvyTheme::new();
        println!("{}{}", prefix, theme.format_error(msg));
    }

    fn finish_skipped(&mut self, msg: &str) {
        let prefix = " ".repeat(self.indent);
        let theme = BivvyTheme::new();
        println!("{}{}", prefix, theme.format_skipped(msg));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn non_interactive_is_not_interactive() {
        let ui = NonInteractiveUI::new(OutputMode::Normal);
        assert!(!ui.is_interactive());
    }

    #[test]
    fn prompt_uses_default() {
        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
        let prompt = Prompt {
            key: "test".to_string(),
            question: "Test?".to_string(),
            prompt_type: PromptType::Input,
            default: Some("default_value".to_string()),
        };

        let result = ui.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "default_value");
    }

    #[test]
    fn prompt_fails_without_default() {
        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
        let prompt = Prompt {
            key: "test".to_string(),
            question: "Test?".to_string(),
            prompt_type: PromptType::Input,
            default: None,
        };

        let result = ui.prompt(&prompt);
        assert!(result.is_err());
    }

    #[test]
    fn prompt_uses_env_override() {
        let mut overrides = HashMap::new();
        overrides.insert("BIVVY_PROMPT_TEST".to_string(), "override".to_string());

        let mut ui = NonInteractiveUI::with_overrides(OutputMode::Normal, overrides);
        let prompt = Prompt {
            key: "test".to_string(),
            question: "Test?".to_string(),
            prompt_type: PromptType::Input,
            default: Some("default".to_string()),
        };

        let result = ui.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "override");
    }

    #[test]
    fn output_mode_preserved() {
        let ui = NonInteractiveUI::new(OutputMode::Quiet);
        assert_eq!(ui.output_mode(), OutputMode::Quiet);
    }

    #[test]
    fn noop_spinner_methods() {
        let mut spinner = NoopSpinner { indent: 0 };
        spinner.set_message("test");
        spinner.finish_success("done");
    }

    #[test]
    fn noop_spinner_error() {
        let mut spinner = NoopSpinner { indent: 0 };
        spinner.finish_error("failed");
    }

    #[test]
    fn noop_spinner_skipped() {
        let mut spinner = NoopSpinner { indent: 0 };
        spinner.finish_skipped("skipped");
    }

    #[test]
    fn multiselect_prompt_uses_default() {
        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
        let prompt = Prompt {
            key: "steps".to_string(),
            question: "Select steps".to_string(),
            prompt_type: PromptType::MultiSelect { options: vec![] },
            default: Some("bundler,cargo".to_string()),
        };

        let result = ui.prompt(&prompt).unwrap();
        assert!(matches!(result, PromptResult::Strings(_)));
        assert_eq!(result.as_string(), "bundler,cargo");
    }

    #[test]
    fn multiselect_prompt_uses_env_override() {
        let mut overrides = HashMap::new();
        overrides.insert("BIVVY_PROMPT_STEPS".to_string(), "npm".to_string());

        let mut ui = NonInteractiveUI::with_overrides(OutputMode::Normal, overrides);
        let prompt = Prompt {
            key: "steps".to_string(),
            question: "Select steps".to_string(),
            prompt_type: PromptType::MultiSelect { options: vec![] },
            default: Some("bundler,cargo".to_string()),
        };

        let result = ui.prompt(&prompt).unwrap();
        assert!(matches!(result, PromptResult::Strings(_)));
        assert_eq!(result.as_string(), "npm");
    }

    #[test]
    fn ci_mode_is_stored() {
        let ui = NonInteractiveUI::with_ci(OutputMode::Normal, true);
        assert!(ui.is_ci);
    }

    #[test]
    fn non_ci_mode_default_for_with_overrides() {
        let ui = NonInteractiveUI::with_overrides(OutputMode::Normal, HashMap::new());
        assert!(!ui.is_ci);
    }

    #[test]
    fn ci_mode_suppresses_workflow_progress() {
        // In CI mode, show_workflow_progress should return early.
        // We verify this doesn't panic and the method is callable.
        // (stdout output is suppressed by the early return, which we
        // can't easily capture, but the is_ci flag test above confirms
        // the flag is set correctly for the early return path.)
        let mut ui = NonInteractiveUI::with_ci(OutputMode::Normal, true);
        ui.show_workflow_progress(1, 5, Duration::from_secs(1));
        // No panic = success. In CI mode this is a no-op.
    }
}

//! CLI argument definitions.
//!
//! This module defines all CLI arguments using clap's derive macros.
//! The main entry point is the [`Cli`] struct.

use clap::{Parser, Subcommand};
use clap_complete::Shell;
use std::path::PathBuf;

/// Bivvy - Development environment setup automation.
#[derive(Debug, Parser)]
#[command(name = "bivvy")]
#[command(author, version, about, long_about = None)]
#[command(propagate_version = true)]
pub struct Cli {
    /// Path to config file (overrides default .bivvy/config.yml)
    #[arg(short, long, global = true)]
    pub config: Option<PathBuf>,

    /// Path to project root (overrides current directory)
    #[arg(short, long, global = true)]
    pub project: Option<PathBuf>,

    /// Show verbose output
    #[arg(short, long, global = true)]
    pub verbose: bool,

    /// Minimal output
    #[arg(short, long, global = true)]
    pub quiet: bool,

    /// Disable colored output
    #[arg(long, global = true)]
    pub no_color: bool,

    /// Enable debug logging
    #[arg(long, global = true)]
    pub debug: bool,

    #[command(subcommand)]
    pub command: Option<Commands>,
}

use super::commands::cache::CacheArgs;
use super::commands::feedback::FeedbackArgs;

/// Available subcommands.
#[derive(Debug, Subcommand)]
pub enum Commands {
    /// Run setup workflow (default if no command specified)
    Run(RunArgs),

    /// Initialize Bivvy configuration for a project
    Init(InitArgs),

    /// Show current setup status
    Status(StatusArgs),

    /// List available steps and workflows
    List(ListArgs),

    /// Show last run information
    Last(LastArgs),

    /// Show execution history
    History(HistoryArgs),

    /// Validate configuration files
    Lint(LintArgs),

    /// Show resolved configuration
    Config(ConfigArgs),

    /// Manage template cache
    Cache(CacheArgs),

    /// Capture and manage feedback
    Feedback(FeedbackArgs),

    /// Generate shell completions
    Completions(CompletionsArgs),
}

/// Arguments for the `run` command.
#[derive(Debug, Clone, clap::Args)]
pub struct RunArgs {
    /// Workflow to run
    #[arg(short, long, default_value = "default")]
    pub workflow: String,

    /// Run only specified steps (comma-separated)
    #[arg(long, value_delimiter = ',')]
    pub only: Vec<String>,

    /// Skip specified steps (comma-separated)
    #[arg(long, value_delimiter = ',')]
    pub skip: Vec<String>,

    /// How to handle skipped step dependencies
    #[arg(long, default_value = "skip_with_dependents")]
    pub skip_behavior: String,

    /// Force re-run of specified steps (comma-separated)
    #[arg(short, long, value_delimiter = ',')]
    pub force: Vec<String>,

    /// Resume an interrupted run
    #[arg(long)]
    pub resume: bool,

    /// Save prompt answers for future runs
    #[arg(long)]
    pub save_preferences: bool,

    /// Preview commands without executing
    #[arg(long)]
    pub dry_run: bool,

    /// Use defaults, no prompts
    #[arg(long)]
    pub non_interactive: bool,

    /// Deprecated: use --non-interactive and --env ci instead
    #[arg(long, hide = true)]
    pub ci: bool,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

impl Default for RunArgs {
    fn default() -> Self {
        Self {
            workflow: "default".to_string(),
            only: Vec::new(),
            skip: Vec::new(),
            skip_behavior: "skip_with_dependents".to_string(),
            force: Vec::new(),
            resume: false,
            save_preferences: false,
            dry_run: false,
            non_interactive: false,
            ci: false,
            env: None,
        }
    }
}

/// Arguments for the `init` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct InitArgs {
    /// Generate minimal config without prompts
    #[arg(long)]
    pub minimal: bool,

    /// Start from a specific template
    #[arg(long)]
    pub template: Option<String>,

    /// Copy configuration from another project
    #[arg(long)]
    pub from: Option<String>,

    /// Overwrite existing configuration
    #[arg(long)]
    pub force: bool,
}

/// Arguments for the `status` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct StatusArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Show status for specific step
    #[arg(long)]
    pub step: Option<String>,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

/// Arguments for the `list` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct ListArgs {
    /// List only steps
    #[arg(long)]
    pub steps_only: bool,

    /// List only workflows
    #[arg(long)]
    pub workflows_only: bool,

    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

/// Arguments for the `last` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct LastArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Show details for specific step
    #[arg(long)]
    pub step: Option<String>,

    /// Show all runs
    #[arg(long)]
    pub all: bool,

    /// Include command output
    #[arg(long)]
    pub output: bool,
}

/// Arguments for the `history` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct HistoryArgs {
    /// Filter by step name
    #[arg(long)]
    pub step: Option<String>,

    /// Number of runs to show
    #[arg(long)]
    pub limit: Option<usize>,

    /// Show runs since duration (e.g., "1h", "7d", "30m")
    #[arg(long)]
    pub since: Option<String>,

    /// Show detailed view with steps for each run
    #[arg(long)]
    pub detail: bool,

    /// Output as JSON
    #[arg(long)]
    pub json: bool,
}

/// Arguments for the `lint` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct LintArgs {
    /// Output format: human, json, sarif
    #[arg(long, default_value = "human")]
    pub format: String,

    /// Auto-fix simple issues
    #[arg(long)]
    pub fix: bool,

    /// Treat warnings as errors
    #[arg(long)]
    pub strict: bool,
}

/// Arguments for the `config` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct ConfigArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Output as YAML
    #[arg(long)]
    pub yaml: bool,

    /// Show fully merged config
    #[arg(long)]
    pub merged: bool,
}

/// Arguments for the `completions` command.
#[derive(Debug, Clone, clap::Args)]
pub struct CompletionsArgs {
    /// Shell to generate completions for
    #[arg(value_enum)]
    pub shell: Shell,
}

