  1→//! Platform-specific shell detection.
  2→
  3→use std::path::PathBuf;
  4→
  5→/// Information about the current shell environment.
  6→#[derive(Debug, Clone)]
  7→pub struct ShellInfo {
  8→    /// Shell executable path.
  9→    pub executable: PathBuf,
 10→
 11→    /// Shell name (bash, zsh, fish, powershell, cmd).
 12→    pub name: ShellType,
 13→
 14→    /// Config files that affect this shell.
 15→    pub config_files: Vec<PathBuf>,
 16→
 17→    /// Command to reload the shell.
 18→    pub reload_command: String,
 19→}
 20→
 21→/// Known shell types.
 22→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 23→pub enum ShellType {
 24→    Bash,
 25→    Zsh,
 26→    Fish,
 27→    PowerShell,
 28→    Cmd,
 29→    Unknown,
 30→}
 31→
 32→impl ShellType {
 33→    /// Parse shell type from executable name.
 34→    pub fn from_executable(exe: &str) -> Self {
 35→        let name = std::path::Path::new(exe)
 36→            .file_stem()
 37→            .and_then(|s| s.to_str())
 38→            .unwrap_or("")
 39→            .to_lowercase();
 40→
 41→        match name.as_str() {
 42→            "bash" => ShellType::Bash,
 43→            "zsh" => ShellType::Zsh,
 44→            "fish" => ShellType::Fish,
 45→            "powershell" | "pwsh" => ShellType::PowerShell,
 46→            "cmd" => ShellType::Cmd,
 47→            _ => ShellType::Unknown,
 48→        }
 49→    }
 50→}
 51→
 52→/// Detect the current shell environment.
 53→pub fn detect_shell() -> ShellInfo {
 54→    let executable = get_shell_executable();
 55→    let shell_type = ShellType::from_executable(&executable.to_string_lossy());
 56→
 57→    ShellInfo {
 58→        executable: executable.clone(),
 59→        name: shell_type,
 60→        config_files: get_config_files(shell_type),
 61→        reload_command: get_reload_command(shell_type, &executable),
 62→    }
 63→}
 64→
 65→fn get_shell_executable() -> PathBuf {
 66→    if cfg!(target_os = "windows") {
 67→        std::env::var("COMSPEC")
 68→            .map(PathBuf::from)
 69→            .unwrap_or_else(|_| PathBuf::from("cmd.exe"))
 70→    } else {
 71→        std::env::var("SHELL")
 72→            .map(PathBuf::from)
 73→            .unwrap_or_else(|_| PathBuf::from("/bin/sh"))
 74→    }
 75→}
 76→
 77→fn get_config_files(shell_type: ShellType) -> Vec<PathBuf> {
 78→    let home = dirs::home_dir().unwrap_or_default();
 79→
 80→    match shell_type {
 81→        ShellType::Bash => vec![
 82→            home.join(".bashrc"),
 83→            home.join(".bash_profile"),
 84→            home.join(".profile"),
 85→        ],
 86→        ShellType::Zsh => vec![
 87→            home.join(".zshrc"),
 88→            home.join(".zprofile"),
 89→            home.join(".zshenv"),
 90→        ],
 91→        ShellType::Fish => vec![home.join(".config/fish/config.fish")],
 92→        ShellType::PowerShell => {
 93→            if let Some(docs) = dirs::document_dir() {
 94→                vec![
 95→                    docs.join("PowerShell/Microsoft.PowerShell_profile.ps1"),
 96→                    docs.join("WindowsPowerShell/Microsoft.PowerShell_profile.ps1"),
 97→                ]
 98→            } else {
 99→                vec![]
100→            }
101→        }
102→        ShellType::Cmd | ShellType::Unknown => vec![],
103→    }
104→}
105→
106→fn get_reload_command(shell_type: ShellType, executable: &std::path::Path) -> String {
107→    match shell_type {
108→        ShellType::Bash | ShellType::Zsh => {
109→            format!("exec {} && bivvy run --continue", executable.display())
110→        }
111→        ShellType::Fish => "exec fish && bivvy run --continue".to_string(),
112→        ShellType::PowerShell => "& $PROFILE; bivvy run --continue".to_string(),
113→        ShellType::Cmd => "start cmd /k \"bivvy run --continue\"".to_string(),
114→        ShellType::Unknown => {
115→            "# Please restart your shell and run: bivvy run --continue".to_string()
116→        }
117→    }
118→}
119→
120→/// Check if running in a CI environment.
121→///
122→/// Used to auto-detect CI and force non-interactive mode in `main()`,
123→/// and to suppress noisy progress bars in [`NonInteractiveUI`](crate::ui::NonInteractiveUI).
124→/// Checks common CI environment variables: `CI`, `GITHUB_ACTIONS`,
125→/// `GITLAB_CI`, `CIRCLECI`, `TRAVIS`, `JENKINS_URL`.
126→pub fn is_ci() -> bool {
127→    std::env::var("CI").is_ok()
128→        || std::env::var("GITHUB_ACTIONS").is_ok()
129→        || std::env::var("GITLAB_CI").is_ok()
130→        || std::env::var("CIRCLECI").is_ok()
131→        || std::env::var("TRAVIS").is_ok()
132→        || std::env::var("JENKINS_URL").is_ok()
133→}
134→
135→/// Check if running as root/admin.
136→pub fn is_elevated() -> bool {
137→    #[cfg(unix)]
138→    {
139→        // SAFETY: geteuid() is a simple syscall that returns the effective user ID
140→        unsafe { libc::geteuid() == 0 }
141→    }
142→
143→    #[cfg(windows)]
144→    {
145→        std::env::var("ADMIN").is_ok()
146→    }
147→
148→    #[cfg(not(any(unix, windows)))]
149→    {
150→        false
151→    }
152→}
153→
154→#[cfg(test)]
155→mod tests {
156→    use super::*;
157→
158→    #[test]
159→    fn shell_type_from_executable() {
160→        assert_eq!(ShellType::from_executable("/bin/bash"), ShellType::Bash);
161→        assert_eq!(ShellType::from_executable("/usr/bin/zsh"), ShellType::Zsh);
162→        assert_eq!(ShellType::from_executable("/usr/bin/fish"), ShellType::Fish);
163→        assert_eq!(ShellType::from_executable("pwsh"), ShellType::PowerShell);
164→        assert_eq!(ShellType::from_executable("cmd.exe"), ShellType::Cmd);
165→        assert_eq!(ShellType::from_executable("unknown"), ShellType::Unknown);
166→    }
167→
168→    #[test]
169→    fn detect_shell_returns_info() {
170→        let info = detect_shell();
171→        assert!(!info.executable.as_os_str().is_empty());
172→    }
173→
174→    #[test]
175→    fn config_files_for_bash() {
176→        let files = get_config_files(ShellType::Bash);
177→        assert!(files.iter().any(|f| f.ends_with(".bashrc")));
178→    }
179→
180→    #[test]
181→    fn config_files_for_zsh() {
182→        let files = get_config_files(ShellType::Zsh);
183→        assert!(files.iter().any(|f| f.ends_with(".zshrc")));
184→    }
185→
186→    #[test]
187→    fn reload_command_includes_bivvy_continue() {
188→        let cmd = get_reload_command(ShellType::Bash, &PathBuf::from("/bin/bash"));
189→        assert!(cmd.contains("--continue"));
190→    }
191→
192→    #[test]
193→    fn is_ci_detects_environment() {
194→        // Just ensure function doesn't panic
195→        let _ = is_ci();
196→    }
197→}
