  1→//! SARIF output formatter.
  2→//!
  3→//! SARIF (Static Analysis Results Interchange Format) is an OASIS standard
  4→//! for static analysis tools, supported by GitHub, VS Code, and other tools.
  5→
  6→use super::LintFormatter;
  7→use crate::lint::{LintDiagnostic, Severity};
  8→use serde::Serialize;
  9→use std::collections::HashSet;
 10→use std::io::Write;
 11→
 12→/// SARIF version we generate.
 13→const SARIF_VERSION: &str = "2.1.0";
 14→const SARIF_SCHEMA: &str = "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json";
 15→
 16→/// Formats lint output as SARIF.
 17→pub struct SarifFormatter {
 18→    /// Tool name to report.
 19→    pub tool_name: String,
 20→    /// Tool version to report.
 21→    pub tool_version: String,
 22→}
 23→
 24→#[derive(Serialize)]
 25→#[serde(rename_all = "camelCase")]
 26→struct SarifLog {
 27→    #[serde(rename = "$schema")]
 28→    schema: &'static str,
 29→    version: &'static str,
 30→    runs: Vec<SarifRun>,
 31→}
 32→
 33→#[derive(Serialize)]
 34→#[serde(rename_all = "camelCase")]
 35→struct SarifRun {
 36→    tool: SarifTool,
 37→    results: Vec<SarifResult>,
 38→}
 39→
 40→#[derive(Serialize)]
 41→#[serde(rename_all = "camelCase")]
 42→struct SarifTool {
 43→    driver: SarifDriver,
 44→}
 45→
 46→#[derive(Serialize)]
 47→#[serde(rename_all = "camelCase")]
 48→struct SarifDriver {
 49→    name: String,
 50→    version: String,
 51→    rules: Vec<SarifRule>,
 52→}
 53→
 54→#[derive(Serialize)]
 55→#[serde(rename_all = "camelCase")]
 56→struct SarifRule {
 57→    id: String,
 58→    short_description: SarifMessage,
 59→}
 60→
 61→#[derive(Serialize)]
 62→#[serde(rename_all = "camelCase")]
 63→struct SarifResult {
 64→    rule_id: String,
 65→    level: &'static str,
 66→    message: SarifMessage,
 67→    #[serde(skip_serializing_if = "Vec::is_empty")]
 68→    locations: Vec<SarifLocation>,
 69→}
 70→
 71→#[derive(Serialize)]
 72→struct SarifMessage {
 73→    text: String,
 74→}
 75→
 76→#[derive(Serialize)]
 77→#[serde(rename_all = "camelCase")]
 78→struct SarifLocation {
 79→    physical_location: SarifPhysicalLocation,
 80→}
 81→
 82→#[derive(Serialize)]
 83→#[serde(rename_all = "camelCase")]
 84→struct SarifPhysicalLocation {
 85→    artifact_location: SarifArtifactLocation,
 86→    #[serde(skip_serializing_if = "Option::is_none")]
 87→    region: Option<SarifRegion>,
 88→}
 89→
 90→#[derive(Serialize)]
 91→struct SarifArtifactLocation {
 92→    uri: String,
 93→}
 94→
 95→#[derive(Serialize)]
 96→#[serde(rename_all = "camelCase")]
 97→struct SarifRegion {
 98→    start_line: usize,
 99→    #[serde(skip_serializing_if = "Option::is_none")]
100→    start_column: Option<usize>,
101→}
102→
103→impl SarifFormatter {
104→    /// Create a new SARIF formatter.
105→    pub fn new(tool_name: impl Into<String>, tool_version: impl Into<String>) -> Self {
106→        Self {
107→            tool_name: tool_name.into(),
108→            tool_version: tool_version.into(),
109→        }
110→    }
111→
112→    fn severity_to_level(severity: Severity) -> &'static str {
113→        match severity {
114→            Severity::Hint => "note",
115→            Severity::Warning => "warning",
116→            Severity::Error => "error",
117→        }
118→    }
119→}
120→
121→impl LintFormatter for SarifFormatter {
122→    fn format<W: Write>(
123→        &self,
124→        diagnostics: &[LintDiagnostic],
125→        writer: &mut W,
126→    ) -> std::io::Result<()> {
127→        // Collect unique rule IDs
128→        let rule_ids: HashSet<_> = diagnostics.iter().map(|d| &d.rule_id).collect();
129→
130→        let rules: Vec<_> = rule_ids
131→            .iter()
132→            .map(|id| SarifRule {
133→                id: id.0.clone(),
134→                short_description: SarifMessage {
135→                    text: format!("Rule {}", id.0),
136→                },
137→            })
138→            .collect();
139→
140→        let results: Vec<_> = diagnostics
141→            .iter()
142→            .map(|d| {
143→                let locations = d
144→                    .span
145→                    .as_ref()
146→                    .map(|span| {
147→                        vec![SarifLocation {
148→                            physical_location: SarifPhysicalLocation {
149→                                artifact_location: SarifArtifactLocation {
150→                                    uri: span.file.display().to_string(),
151→                                },
152→                                region: Some(SarifRegion {
153→                                    start_line: span.start_line,
154→                                    start_column: if span.start_col > 1 {
155→                                        Some(span.start_col)
156→                                    } else {
157→                                        None
158→                                    },
159→                                }),
160→                            },
161→                        }]
162→                    })
163→                    .unwrap_or_default();
164→
165→                SarifResult {
166→                    rule_id: d.rule_id.0.clone(),
167→                    level: Self::severity_to_level(d.severity),
168→                    message: SarifMessage {
169→                        text: d.message.clone(),
170→                    },
171→                    locations,
172→                }
173→            })
174→            .collect();
175→
176→        let log = SarifLog {
177→            schema: SARIF_SCHEMA,
178→            version: SARIF_VERSION,
179→            runs: vec![SarifRun {
180→                tool: SarifTool {
181→                    driver: SarifDriver {
182→                        name: self.tool_name.clone(),
183→                        version: self.tool_version.clone(),
184→                        rules,
185→                    },
186→                },
187→                results,
188→            }],
189→        };
190→
191→        serde_json::to_writer_pretty(writer, &log).map_err(std::io::Error::other)?;
192→
193→        Ok(())
194→    }
195→}
